//! Tests names generated by `NameTable`.

use greybel_transpiler::names::{Charset, NameTable};
use serde_json::{Value, json};

use crate::support::strings;

/// Checks generated names for fixture sequences with obfuscation enabled and disabled and with forbidden names.
/// Snapshots were originally recorded from the TypeScript generator.
#[test]
fn should_give_names_in_sequence() {
    let inputs: Value = serde_json::from_str(include_str!("fixtures/greybel/name-sequences.json"))
        .expect("valid inputs");
    let inputs = inputs.as_array().expect("array of sequences");

    let given: Vec<Value> = inputs
        .iter()
        .map(|input| {
            let obfuscation = input["obfuscation"].as_bool().expect("bool");
            let forbidden = strings(&input["forbidden"]).into_iter().flatten();
            let mut names =
                NameTable::new(Charset::variables(obfuscation).chars()).forbid(forbidden);
            let sequence: Vec<String> = strings(&input["sequence"]).into_iter().flatten().collect();

            for original in &sequence {
                names.create(original);
            }

            let given: Vec<Option<&str>> = sequence
                .iter()
                .map(|original| names.get(original))
                .collect();

            json!({ "obfuscation": obfuscation, "names": given })
        })
        .collect();

    insta::assert_yaml_snapshot!(given);
}
